from qb import q, write

HC = ["backend-developer", "full-stack-developer", "python-developer"]
AI = ["junior-ai-engineer", "ai-ml-engineer-intern", "python-developer", "backend-developer"]
ITEMS = [
    q("healthcare-it", "easy", ["privacy"], "Why must a healthcare application treat patient records more carefully than an ordinary web app, and what are three basic protections?", "Patient data is highly sensitive and leaking it harms people, so access must be limited and traceable. Basic protections are role-based access, encryption in transit and at rest, and audit logs of who viewed or changed a record. Follow the privacy rules of the country and the client.", ["Highly sensitive data", "Role-based access and encryption", "Audit logs"], ["What would you log, and what must you never log?"]),
    q("healthcare-it", "medium", ["audit"], "How would you design audit logging so that every change to a patient record can be traced to a user and time?", "Write an append-only audit entry for each create, update and delete with the user, time, record, action and the old and new values or a reference to them, in the same transaction as the change. Protect the log from edits and limit who can read it.", ["Append-only entries", "Written in the same transaction", "Protect and restrict the log"], ["How would you keep the log from growing without limit?"]),
    q("healthcare-it", "hard", ["interoperability"], "Hospital systems exchange data in standard formats such as HL7 or FHIR. Why do standards matter and what problems arise when two systems disagree?", "Standards let different systems exchange data without custom work for every pair. Problems appear with different code sets, missing or optional fields and mismatched units, so you validate incoming data, map codes explicitly and reject or flag records that cannot be trusted.", ["Standard formats reduce custom work", "Mapping codes and units", "Validate and flag bad records"], ["How would you test an integration with another hospital system?"]),
    q("healthcare-it", "medium", ["data-integrity"], "Two receptionists edit the same appointment at the same time. How do you stop one change silently overwriting the other?", "Use optimistic concurrency: store a version or timestamp, include it when saving and reject the update if it changed, then show the user the conflict. Pessimistic locking is an option for short critical edits.", ["Version column", "Reject stale updates", "Show the conflict to the user"], ["What are the trade-offs against locking?"]),
    q("csharp", "easy", ["value-reference"], "What is the difference between value types and reference types in C#?", "Value types such as int and struct hold their data directly and are copied on assignment, while reference types such as classes hold a reference to an object so two variables can point to the same object. This affects copying, nulls and performance.", ["Copy vs shared reference", "int, struct vs class", "Effects on assignment"], ["What does boxing mean?"]),
    q("csharp", "medium", ["linq"], "What is LINQ and what is the difference between deferred and immediate execution?", "LINQ lets you query collections with a consistent syntax such as Where and Select. Most queries are deferred, meaning they run when you iterate, while methods like ToList or Count run immediately; deferred queries re-run every time they are enumerated.", ["Query syntax over collections", "Deferred execution", "ToList forces execution"], ["How can deferred execution cause a bug?"]),
    q("csharp", "medium", ["async"], "How do async and await work in C# and why should you avoid blocking on async code with .Result?", "async methods return a Task and await releases the thread while waiting, so the thread can serve other work. Blocking with .Result or .Wait can deadlock in some contexts and wastes threads, so use await all the way up.", ["Task and await", "Thread is released while waiting", "Avoid .Result and .Wait"], ["When would you use Task.WhenAll?"]),
    q("dotnet", "medium", ["dependency-injection"], "What is dependency injection in ASP.NET Core and what do transient, scoped and singleton lifetimes mean?", "Dependency injection supplies a class with the objects it needs instead of creating them itself, which makes testing easy. Transient creates a new instance each time, scoped one per request and singleton one for the application's lifetime.", ["Dependencies are supplied", "Three lifetimes", "Easier testing"], ["What goes wrong if a singleton uses a scoped service?"]),
    q("dotnet", "medium", ["entity-framework"], "What is Entity Framework and how do you avoid performance problems such as loading too much data?", "Entity Framework maps database tables to classes and builds SQL from LINQ. Avoid loading too much by selecting only the needed columns, using AsNoTracking for read-only queries, loading related data deliberately and adding indexes.", ["ORM mapping", "Select only needed data", "AsNoTracking and indexes"], ["How can you see the SQL that EF generates?"]),
    q("dotnet", "hard", ["middleware"], "Explain the ASP.NET Core request pipeline and where you would put authentication and error handling.", "A request passes through a chain of middleware components in order, and each can handle it or call the next. Error handling goes first so it catches everything after it, and authentication comes before authorisation and the endpoints that need it.", ["Ordered middleware chain", "Error handling first", "Authentication before authorisation"], ["What happens if the order is wrong?"]),
    q("sql", "easy", ["joins"], "What is the difference between INNER JOIN and LEFT JOIN, and how would you list patients who have no appointments?", "INNER JOIN returns only matching rows, LEFT JOIN keeps all left rows. To find patients without appointments, left join appointments and keep rows where the appointment key is NULL, or use NOT EXISTS.", ["Matching vs all left rows", "LEFT JOIN with IS NULL", "NOT EXISTS alternative"], ["Which is faster on a large table?"]),
    q("sql", "medium", ["stored-procedures"], "What are stored procedures and views and when would you use each?", "A stored procedure is saved database code that can take parameters and change data, useful for repeated server-side logic. A view is a saved query that behaves like a table, useful for simplifying reads and limiting exposed columns. Keep business logic in one place to avoid duplication.", ["Procedure: reusable logic", "View: saved query", "Avoid scattering logic"], ["What are the downsides of heavy logic in procedures?"]),
    q("sql", "hard", ["performance"], "A patient search by name is slow. How do you speed it up?", "Check the plan, then index the searched columns, avoid functions or leading wildcards that block the index, consider normalised search columns or full-text search and paginate results. Measure after the change.", ["Query plan first", "Index and avoid blocking patterns", "Full-text search and paging"], ["Why does LIKE '%name' not use a normal index?"]),
    q("rest-api", "medium", ["design"], "How would you design API endpoints for patients and their appointments, including filtering and error responses?", "Use resources such as /patients and /patients/{id}/appointments, support filters and pagination through query parameters, return consistent errors with proper status codes and never leak internal details. Protect each endpoint with authorisation checks.", ["Resource-based URLs", "Filtering and pagination", "Consistent errors and authorisation"], ["How do you version the API?"]),
    q("rest-api", "medium", ["validation"], "Why must the server validate input even if the front end already does?", "Client checks can be bypassed with direct requests, so the server is the only trusted place to enforce rules. Validate types, ranges and required fields and return clear errors, and sanitise output.", ["Client checks can be bypassed", "Server enforces rules", "Clear validation errors"], ["What is mass assignment and how do you prevent it?"]),
    q("oop", "medium", ["solid"], "Explain the open/closed principle and the Liskov substitution principle with short examples.", "Open/closed means code is open to extension but closed to modification, such as adding a new report type by adding a class. Liskov means a subclass must be usable wherever its parent is expected without breaking behaviour, so a subclass should not throw for operations the parent supports.", ["Extend without editing", "Subclasses honour the parent's contract", "Examples for both"], ["Give an example that breaks Liskov."]),
    q("testing", "medium", ["unit-testing"], "How do you unit test a service that depends on a database and an email provider?", "Depend on interfaces and replace the database and email provider with fakes or mocks in tests, check the behaviour and results, and keep a few integration tests with a test database. Dependency injection makes the swap simple.", ["Depend on interfaces", "Fakes in unit tests", "Few integration tests"], ["When is a mock the wrong tool?"]),
    q("ai-health", "medium", ["llm", "safety"], "A client wants an AI feature to summarise doctors' notes. What risks do you raise and how do you reduce them?", "Raise privacy of patient data sent to a model, wrong or invented details in summaries, and over-trust by staff. Reduce them with de-identification, a provider agreement, clear labelling as a draft, human review before anything is saved and tests on realistic notes.", ["Privacy and third-party processing", "Hallucination risk", "Human review and labelling"], ["How would you measure summary quality?"], roles=AI),
    q("ai-health", "hard", ["ml-evaluation"], "How would you evaluate a model that predicts which patients will miss an appointment, and what could go wrong ethically?", "Use a time-based split and metrics such as precision, recall and calibration, and compare with a simple baseline. Check performance across groups to avoid unfair treatment, and use predictions to help patients, for example with reminders, not to deny care.", ["Time-based split and baseline", "Per-group performance", "Use to help, not to deny care"], ["What data would you refuse to use?"], roles=AI),
    q("python", "medium", ["python", "data"], "How would you clean a CSV of patient visits with inconsistent dates and duplicate rows in Python?", "Parse dates with explicit formats and flag failures, normalise text, drop exact duplicates and decide a rule for near duplicates, validate required fields and log what was changed. Keep the raw file untouched.", ["Parse and flag bad dates", "Duplicate rules", "Log changes, keep raw data"], ["How would you test the cleaning code?"], roles=AI),
    q("devops", "medium", ["deployment"], "How do you release a change to a system that hospitals use every day with minimal risk?", "Test in a staging environment that mirrors production, release in a quiet window or gradually, use feature flags, have a rehearsed rollback and monitor errors right after release. Communicate with support teams.", ["Staging and gradual release", "Feature flags and rollback", "Monitor and communicate"], ["What would make you stop a release?"]),
    q("healthcare-scenario", "medium", ["incidents"], "Scenario: a nurse reports that a patient's allergy information is missing in the system. How do you respond?", "Treat it as urgent: confirm the issue, help the nurse find the information through a safe backup channel, then investigate through audit logs and recent changes to see whether data was lost or hidden. Fix the cause, restore data and report the incident properly.", ["Safety first", "Use audit logs to investigate", "Fix, restore, report"], ["What would you add to prevent it happening again?"], kind="scenario"),
    q("healthcare-scenario", "hard", ["design"], "Scenario: design an appointment reminder system that sends messages to thousands of patients each morning without sending duplicates.", "Select the day's appointments, create one reminder record per appointment with a unique constraint, send through a queue with retries and mark each as sent, so a rerun skips completed ones. Respect patients' contact preferences and log delivery.", ["One reminder record per appointment", "Queue with retries", "Idempotent and respects preferences"], ["What if the SMS provider is down for an hour?"], kind="scenario"),
    q("healthcare-scenario", "easy", ["teamwork"], "Scenario: a client asks for a feature that conflicts with a privacy rule. How do you handle it?", "Explain the rule and the risk politely, involve your lead or compliance contact and propose an alternative that meets the need without breaking the rule. Do not quietly ignore or implement it.", ["Do not silently comply", "Escalate to the right person", "Offer an alternative"], ["How do you document the decision?"], kind="scenario"),
    q("project", "easy", ["projects"], "Describe a project where correctness mattered. How did you check your data and logic?", "A strong answer names the project and why mistakes were costly, the checks you added such as validation and tests, one bug you found and your own contribution.", ["Why correctness mattered", "Validation and tests", "A real bug and fix"], ["What would you test next?"], kind="scenario", roles=HC + ["frontend-developer"]),
]


def build():
    return write("curemd", HC, ITEMS)


if __name__ == "__main__":
    build()
